// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.JoinDispatchTestAccess;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Milestone 1 of the three-tier parity ExecPlan (.agent/three-tier-parity-execplan.md): with
 * {@code rdf4j.lmdb.wcoj.streamingFrontiers.enabled=true}, a leapfrog level with more than one adjacency-representable
 * member must intersect the larger members in place — seeking inside the (neighbor, context)-ordered adjacency run
 * instead of copying it into a value array — observable through the {@code FRONTIERS_STREAMED} counter, while producing
 * results (and solution multiplicities) identical to the flag-off run.
 */
public class LmdbWcojStreamingFrontierTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String STREAMING_FLAG = "rdf4j.lmdb.wcoj.streamingFrontiers.enabled";

	private static final String TRIANGLE = "SELECT ?a ?b ?c WHERE {\n"
			+ "  ?a <" + EX + "knows> ?b .\n"
			+ "  ?b <" + EX + "knows> ?c .\n"
			+ "  ?c <" + EX + "knows> ?a .\n"
			+ "}";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private LmdbStore store;
	private String previousNative;
	private String previousStreaming;

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		restore(NATIVE_FLAG, previousNative);
		restore(STREAMING_FLAG, previousStreaming);
	}

	private static void restore(String key, String previous) {
		if (previous == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, previous);
		}
	}

	@Test
	public void streamingFrontiersIntersectInPlaceWhenEnabled() throws Exception {
		captureProperties();
		openRepositoryWithTriangles();
		prepareAdjacency();

		System.setProperty(NATIVE_FLAG, "true");

		System.clearProperty(STREAMING_FLAG);
		List<String> expected = rows(TRIANGLE);
		assertThat(expected).isNotEmpty();
		assertThat(JoinDispatchTestAccess.leapfrogStreamedFrontiers())
				.as("flag off: every member frontier is materialized")
				.isZero();

		System.setProperty(STREAMING_FLAG, "true");
		long openedBefore = JoinDispatchTestAccess.leapfrogOpened();
		List<String> actual = rows(TRIANGLE);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(JoinDispatchTestAccess.leapfrogOpened()).as("leapfrog must still serve the triangle")
				.isGreaterThan(openedBefore);
		assertThat(JoinDispatchTestAccess.leapfrogStreamedFrontiers())
				.as("members beyond the intersection accumulator must be seeked in place, not copied")
				.isGreaterThan(0);
	}

	@Test
	public void streamingFrontiersDefaultToDisabled() throws Exception {
		captureProperties();
		openRepositoryWithTriangles();
		prepareAdjacency();

		System.setProperty(NATIVE_FLAG, "true");
		System.clearProperty(STREAMING_FLAG);

		assertThat(rows(TRIANGLE)).isNotEmpty();
		assertThat(JoinDispatchTestAccess.leapfrogStreamedFrontiers())
				.as("with the property unset, streaming frontiers must be OFF")
				.isZero();
	}

	@Test
	public void duplicateEdgesAcrossGraphsPreserveMultiplicityUnderStreamingFrontiers() throws Exception {
		captureProperties();
		openRepositoryWithTriangles();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI knows = vf.createIRI(EX, "knows");
			// Duplicate one triangle edge in two named graphs: multiplicity 3 for (a,b), so each triangle
			// solution through that edge must appear three times. Duplicate counts force the materialized path
			// for the member whose final level this is; the other members may still stream.
			conn.add(vf.createIRI(EX, "a"), knows, vf.createIRI(EX, "b"), vf.createIRI(EX, "g1"));
			conn.add(vf.createIRI(EX, "a"), knows, vf.createIRI(EX, "b"), vf.createIRI(EX, "g2"));
		}
		prepareAdjacency();

		System.setProperty(NATIVE_FLAG, "true");

		System.clearProperty(STREAMING_FLAG);
		List<String> expected = rows(TRIANGLE);

		System.setProperty(STREAMING_FLAG, "true");
		List<String> actual = rows(TRIANGLE);

		assertThat(expected).isNotEmpty();
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
	}

	@Test
	public void graphScopedTriangleStaysCorrectUnderStreamingFrontiers() throws Exception {
		captureProperties();
		openRepositoryWithTriangles();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI knows = vf.createIRI(EX, "knows");
			IRI g1 = vf.createIRI(EX, "g1");
			conn.add(vf.createIRI(EX, "x"), knows, vf.createIRI(EX, "y"), g1);
			conn.add(vf.createIRI(EX, "y"), knows, vf.createIRI(EX, "z"), g1);
			conn.add(vf.createIRI(EX, "z"), knows, vf.createIRI(EX, "x"), g1);
		}
		prepareAdjacency();

		String graphTriangle = "SELECT ?a ?b ?c WHERE { GRAPH <" + EX + "g1> {\n"
				+ "  ?a <" + EX + "knows> ?b .\n"
				+ "  ?b <" + EX + "knows> ?c .\n"
				+ "  ?c <" + EX + "knows> ?a .\n"
				+ "} }";

		System.setProperty(NATIVE_FLAG, "true");

		System.clearProperty(STREAMING_FLAG);
		List<String> expected = rows(graphTriangle);

		System.setProperty(STREAMING_FLAG, "true");
		List<String> actual = rows(graphTriangle);

		assertThat(expected).isNotEmpty();
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
	}

	@Test
	public void parallelWorkersStreamFrontiersInPlace() throws Exception {
		captureProperties();
		openRepositoryWithTriangles();
		prepareAdjacency();

		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty("rdf4j.lmdb.wcoj.parallelMinCandidates", "1");
		try {
			System.clearProperty(STREAMING_FLAG);
			List<String> expected = rows(TRIANGLE);

			System.setProperty(STREAMING_FLAG, "true");
			long parallelBefore = JoinDispatchTestAccess.leapfrogParallelRuns();
			List<String> actual = rows(TRIANGLE);

			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
			assertThat(JoinDispatchTestAccess.leapfrogParallelRuns()).as("parallel leapfrog engaged")
					.isGreaterThan(parallelBefore);
			assertThat(JoinDispatchTestAccess.leapfrogStreamedFrontiers())
					.as("worker-computed frontiers must stream too")
					.isGreaterThan(0);
		} finally {
			System.clearProperty("rdf4j.lmdb.wcoj.parallelMinCandidates");
		}
	}

	private void captureProperties() {
		previousNative = System.getProperty(NATIVE_FLAG);
		previousStreaming = System.getProperty(STREAMING_FLAG);
	}

	private void prepareAdjacency() {
		LmdbSailStore backing = store.getBackingStore();
		LmdbDirectAdjacencyStore adjacency = backing.directAdjacencyStore();
		assertThat(adjacency).as("direct adjacency store must be enabled by default").isNotNull();
		assertThat(adjacency.buildNowForTest()).as("direct adjacency build must complete for this store").isTrue();
	}

	private void openRepositoryWithTriangles() {
		JoinDispatchTestAccess.resetMetrics();
		store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc,posc"));
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI knows = vf.createIRI(EX, "knows");
			// Two proper triangles, one self-loop, plus chaff edges that close no triangle.
			IRI a = vf.createIRI(EX, "a");
			IRI b = vf.createIRI(EX, "b");
			IRI c = vf.createIRI(EX, "c");
			IRI d = vf.createIRI(EX, "d");
			IRI e = vf.createIRI(EX, "e");
			IRI f = vf.createIRI(EX, "f");
			IRI h = vf.createIRI(EX, "h");
			conn.add(a, knows, b);
			conn.add(b, knows, c);
			conn.add(c, knows, a);
			conn.add(d, knows, e);
			conn.add(e, knows, f);
			conn.add(f, knows, d);
			conn.add(h, knows, h);
			for (int i = 0; i < 40; i++) {
				conn.add(vf.createIRI(EX, "chaff" + i), knows, vf.createIRI(EX, "chaff" + (i + 1)));
			}
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return rowsOn(conn, query);
		}
	}

	private List<String> rowsOn(SailRepositoryConnection conn, String query) {
		List<String> rows = new ArrayList<>();
		try (var result = conn.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				List<String> parts = new ArrayList<>();
				for (String name : bindings.getBindingNames()) {
					parts.add(name + "=" + bindings.getValue(name));
				}
				parts.sort(String::compareTo);
				rows.add(String.join("|", parts));
			}
		}
		return rows;
	}
}
